List<int> parseNestedParens(String parenString) {
  final result = <int>[];

  void process(int start, int depth) {
    if (start >= parenString.length) return;

    var i = start;
    while (i < parenString.length && parenString[i] == '(') {
      i++;
    }

    // Count the number of opening and closing parentheses to find the innermost level
    int openCount = 0;
    int closeCount = 0;
    for (var j = start; j < parenString.length; j++) {
      if (parenString[j] == '(') openCount++;
      else if (parenString[j] == ')') closeCount++;

      if (openCount > 0 && openCount == closeCount) break;
    }

    // If we found a matching pair
    if (openCount != 0) {
      // Calculate the length of this nested group
      int length = i - start;
      result.add(length);

      // Recursively process the content inside these parentheses
      process(i + 1, depth + 1);

      // Skip over the processed part
      i += openCount * 2;
      process(i, depth); 
    } else {
      // No more nested groups, just add the remaining characters as is
      result.add(parenString.substring(start).length);
    }
  }

  process(0, 0);
  return result;
}
