List<String> getPermutations(String str) {
  int length = str.length;
  List<List<int>> indices = [];

  // Initialize with index list [0]
  List<int> initialIndices = [0];
  indices.add(initialIndices);

  for (int i = 1; i < length; i++) {
    List<List<int>> newIndices = [];
    for (final prevIndices in indices) {
      for (int j = 0; j <= i; j++) {
        List<int> newIndicesList = [...prevIndices];
        newIndicesList.insert(j, i);
        newIndices.add(newIndicesList);
      }
    }
    indices = newIndices;
  }

  List<String> permutations = [];
  for (final permIndices in indices) {
    String permutation = '';
    for (int idx in permIndices) {
      permutation += str[idx];
    }
    permutations.add(permutation);
  }

  return permutations;
}

