String stringSequence(int n) {
  int count = 0;
  String result = '';

  void helper(String current, bool isPrefix) {
    if (isPrefix) {
      if (current.length > 1 && !current.startsWith('a') && !current.endsWith('z')) {
        final nextCharCode = current.codeUnitAt(current.length - 1);
        final nextChar = String.fromCharCode(nextCharCode + 1);
        helper(current + nextChar, false);
        return;
      }

      if (++count == n) {
        result = current;
        return;
      } else {
        for (var i = 0; i < 26; ++i) {
          var c = String.fromCharCode(97 + i);
          helper(current + c, false);
        }
      }
    } else {
      final lastChar = current[current.length - 1];
      final lastCharCode = lastChar.codeUnitAt(0);
      final prevChar = String.fromCharCode(lastCharCode - 1);
      if (lastCharCode >= 98) {
        helper(current + prevChar, true);
      }
    }
  }

  helper('', true);

  return result;
}
