String sortNumbers(String numbers) {
  final List<int> nums = numbers.split(' ').map(int.parse).toList();

  // Check if the input is empty or has only one number, which are already sorted.
  if (nums.length <= 1) return numbers;

  int partition(List<int> arr, int left, int right) {
    var pivotIndex = Random().nextInt(right - left + 1) + left;
    var pivot = arr[pivotIndex];
    arr.removeAt(pivotIndex);
    arr.insertRight(right, pivot); // Place pivot at end

    var i = left; // Index of smaller element
    for (var j = left; j < right; ++j) {
      if (arr[j] < pivot) {
        arr.swap(i, j);
        ++i;
      }
    }
    arr.swap(i, right);
    return i;
  }

  void quickSort(List<int> arr, int left, int right) {
    if (left >= right) return;

    var index = partition(arr, left, right);
    quickSort(arr, left, index - 1);
    quickSort(arr, index + 1, right);
  }

  quickSort(nums, 0, nums.length - 1);
  return nums.map((n) => n.toString()).join(' ');
}
