    var pivotIndex = Random().nextInt(right - left + 1) + left;
    var pivot = arr[pivotIndex];

    // Move pivot to the end temporarily
    arr.removeAt(pivotIndex);
    arr.add(pivot);

    var i = left; // Index where elements less than pivot will be placed

    // Partition the array based on pivot value
    for (int j = left; j < right; j++) {
      if (arr[j] < pivot) {
        // Swap current element with element at position i
        arr.swap(i, j);
        i++;
      }
    }

    // Move pivot to its correct position between elements less than it and greater than it
    arr.swap(i, right);
    return i;
