import 'dart:math';

String sortNumbers(String numbers) {
  final List<int> nums = numbers.split(' ').map(int.parse).toList();

  void quickSort(List<int> list, int left, int right) {
    int i = left;
    int j = right;
    var pivot = list[(left + right) ~/ 2];

    while (i <= j) {
      while (list[i] < pivot) i++;
      while (list[j] > pivot) j--;

      if (i <= j) {
        // Swap elements at positions i and j
        final temp = list[i];
        list[i] = list[j];
        list[j] = temp;

        i++;
        j--;
      }
    }

    if (left < j) quickSort(list, left, j);
    if (right > i) quickSort(list, i, right);
  }

  quickSort(nums, 0, nums.length - 1);
  return nums.map((num) => num.toString()).join(' ');
}
