  if (n < 2) return -1;

  int maxFactor = 0;
  for (int i = 2; i <= sqrt(n); i++) {
    while (n % i == 0) {
      maxFactor = i;
      n ~/= i;
    }
  }

  return n > 1 ? n : maxFactor;
}

