int fruitDistribution(String s, int n) {
  if (s == null || s.isEmpty) return -1;

  final List<int> counts = [];
  for (var c in s.split('')) {
    var count = 0;
    if (c.length > 1 && c[0] == '[') { // handle multi-character fruits
      int i = 1;
      while (i < c.length && c[i] != ']') {
        count += int.tryParse(c[i]) ?? 0;
        i++;
      }
    } else if (c is String && c.isNotEmpty) {
      count = 1; // single character fruits are counted as one
    }
    counts.add(count);
  }

  int totalFruits = counts.fold(0, (sum, e) => sum + e);
  if (totalFruits < n) return -1;

  int distribution = totalFruits ~/ n;
  int remainder = totalFruits % n;

  int result = 0;
  for (int i=0; i<counts.length; i++) {
    if (remainder > 0) {
      result += min(counts[i], distribution+1);
      remainder--;
    } else {
      result += min(counts[i], distribution);
    }
  }

  return result;
}

