int fruitDistribution(String s, int n) {
  if (s.length < n || s.isEmpty) return -1;

  final List<String> fruits = ['apple', 'banana', 'orange', 'grape'];
  final Map<String, int> countMap = {};

  for (var i = 0; i < s.length && fruits.length > 0; ++i) {
    var fruit = s[i];

    if (fruit == 'a' || fruit == 'b' || fruit == 'o') {
      var name = '';

      // Check if the character is part of a fruit name
      while (fruits.isNotEmpty && fruits[0].startsWith(fruit)) {
        name += fruit;
        fruits.removeAt(0);
      }

      if (name.isNotEmpty) {
        countMap[name] = (countMap[name] ?? 0) + 1;
      }
    } else if (fruit == 'g') {
      // Handle grape case separately
      var name = 'grape';
      countMap[name] = (countMap[name] ?? 0) + 1;
      fruits.removeWhere((f) => f == 'grape');
    }
  }

  // Calculate how many times each fruit appears in the string
  final List<int> counts = [];
  for (final key in countMap.keys) {
    counts.add(countMap[key]!);
  }

  // Sort the list to find the minimum number of occurrences of any fruit
  counts.sort();

  // The answer is the total number of distinct fruits that appear at least once in the input string and are present in the array.
  return min(counts.elementAt(0), n) * (counts.elementAt(0) != 0 ? 1 : 0);
}

