String antiShuffle(String s) {
  if (s.isEmpty) return '';

  List<String> words = [];
  String currentWord = '';
  int i = 0;

  while (i < s.length) {
    // Check for the end of a word (space or end of string)
    bool isEndOfWord = false;

    if (i + 1 < s.length && s[i+1] == ' ') {
      isEndOfWord = true;
    } else if (i == s.length - 1) {
      isEndOfWord = true;
    }

    // If it's the start of a new word, reset currentWord and add previous to list
    if (isEndOfWord || i == 0) {
      if (currentWord.isNotEmpty) {
        words.add(currentWord);
        currentWord = '';
      }

      // Handle leading spaces by adding empty strings as needed
      if (i > 0 && s[i-1] != ' ' && s[i] == ' ') {
        words.add('');
      }

      currentWord += s[i];
      i++;
    } else {
      // Otherwise, check if we can form an increasing sequence with next character
      if (i + 2 <= s.length) {
        // Check if current character is less than next one
        if (s[i] < s[i+1]) {
          currentWord += s[i];
          i++;
        } else {
          // Not part of increasing sequence, finalize current word
          words.add(currentWord);
          currentWord = s[i];
          i++;
        }
      } else {
        // Add remaining characters in order
        currentWord += s[i];
        i++;
      }
    }
  }

  // Finalize any remaining currentWord
  if (currentWord.isNotEmpty) {
    words.add(currentWord);
  }

  // Now reconstruct the sentence without shuffling
  String result = '';
  for (int j = 0; j < words.length; j++) {
    if (j > 0 && words[j].isEmpty) {
      // Skip empty strings between words
      continue;
    }
    result += words[j];
    if (j < words.length - 1 && !words[j+1].isEmpty) {
      result += ' ';
    }
  }

  return result;
}
