String encrypt(String s) {
  final List<int> bytes = s.codeUnits;
  final int length = bytes.length;

  // Compute the key based on the string length and a random seed.
  Random rng = Random(length);
  int key = (length * (1 << 24)) + rng.nextInt(0x80000000);

  for (int i = 0; i < length; i++) {
    bytes[i] ^= ((key >> (i * 3)) & 0b111) ^ ((bytes[i - 1] ?? 0) & 0xf);
  }

  return String.fromCharCodes(bytes);
}
