  // If the key is all lowercase or underscores, it's considered snake_cased
  final isSnakeCased = snakeCasedKey != key && !key.contains(RegExp('([A-Z])'));

  final isCamelCased = camelCasedKey != key;

  // For primitives, ensure that:
  // - The key follows proper casing based on its case
  // - The value is of valid types
  final isValidType = [
