  int index = 0;
  while (index < totalDigits) {
    result.add(secondHalf[index]);
    index++;
  }

  if (isEven && totalDigits != 1) {
    index = 0;
    while (index < (totalDigits ~/ 2)) {
      result.insert(index, firstHalf[index]);
      result.add(firstHalf[index]);
      index++;
    }
  } else if (!isEven) {
    index = 0;
    while (index < (totalDigits ~/ 2)) {
      result.insert(index, firstHalf[index]);
      result.add(firstHalf[index]);
      index++;
    }
    result.add(secondHalf[secondHalf.length - 1]); // Middle digit
  }

  return result;
}

