  void dfs(int r, int c, int pathSum) {
    if (r >= rows || c >= cols) return; // out of bounds
    if (pathSum > k) return; // exceed budget

    // Check memo
    if (dp[r][c].containsKey(pathSum)) {
      return dp[r][c][pathSum] ??= 1;
    }

    // Base case: end of the grid
    if (r == rows - 1 && c == cols - 1) {
      dp[r][c][pathSum] = 1;
      return;
    }

    var currentVal = grid[r][c];

    // Try moving to next cell in both directions
    for (var dir in directions) {
      var nr = r + dir == 1 ? r : r + dir;
      var nc = c + dir == 1 ? c : c + dir;

      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        dfs(nr, nc, pathSum + currentVal);
