List<String> _words(String s) {
  if (s == null || s.isEmpty) return [];

  final List<String> result = [];
  int i = 0;
  while (i < s.length) {
    if (_isWordCharacter(s[i])) {
      var j = i + 1;
      while (j < s.length && _isWordCharacter(s[j])) j++;

      // Check for hyphenated words
      bool isHyphenated = false;
      if (j - i > 2) { // At least one hyphen in the middle of a word?
        int k = i + 1, m = j - 1; 
        while (k <= m) {
          if (s[k] == '-') {
            isHyphenated = true;
            break;
          }
          k++;
          m--;
        }   
      }

      String word = s.substring(i, j);
      if (!isHyphenated) {
        result.add(word);
      } else {
        // Split on each hyphen and add individual parts as separate words
        var subWords = word.split('-');
        for (var sw in subWords) {
          if (sw.isNotEmpty) result.add(sw);
        }
      }

      i = j;
    } else {
      i++;
    }
  }
  return result;
}

bool _isWordCharacter(int c) => 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z';

