// Helper function to check if the pattern list is a cyclic permutation of a
bool PatternMatch(List<String> patternList, String a) {
  if (patternList.length != a.length) return false;

  bool match(int start, int end) {
    for (int i = start; i <= end; ++i) {
      if (patternList[i - start] != a[i % a.length]) return false;
    }
    return true;
  }

  for (int i = 0; i < a.length; ++i) {
    if (match(i, i + a.length - 1)) {
      return true;
    }
  }
  return false;
}

