  for(int i=0; i < operator.length; ++i){
    final op = operator[i];
    final val = operand[i+1];

    switch(op){
      case '+':
        result += val;
        break;
      case '-':
        result -= val;
        break;
      case '*':
        result *= val;
        break;
      case '/':
        result /= val;
        break;
      default:
        throw FormatException("Unsupported operation $op at index $i");
    }
  }
  return result;
}

